    def radius(node):
        for t in list(node.getElementsByTagNameNS('http://schemas.openxmlformats.org/officeDocument/2006/math', 't')):
            if t.firstChild and 'ρ' in t.firstChild.data:
                run = t.parentNode
                before, after = t.firstChild.data.split('ρ', 1)
                if before:
                    prefix = run.cloneNode(True)
                    prefix.getElementsByTagNameNS('http://schemas.openxmlformats.org/officeDocument/2006/math', 't')[0].firstChild.data = before
                    run.parentNode.insertBefore(prefix, run)
                replacement = e.math('ρ_{rel}‖h_{ij}‖_2')
                for child in list(replacement.childNodes):
                    run.parentNode.insertBefore(child, run)
                if after:
                    suffix = run.cloneNode(True)
                    suffix.getElementsByTagNameNS('http://schemas.openxmlformats.org/officeDocument/2006/math', 't')[0].firstChild.data = after
                    run.parentNode.insertBefore(suffix, run)
                run.parentNode.removeChild(run)
                return
        raise AssertionError('radius multiplier missing')
    e.transform_math(225, lambda n: any(t.firstChild and 'ρ' in t.firstChild.data for t in n.getElementsByTagNameNS('http://schemas.openxmlformats.org/officeDocument/2006/math', 't')), radius, 29)
    e.whole(227, '其中，$δ_{ij}$为沿增大监督损失方向构造的表示扰动，$ρ_{rel}$为相对扰动系数，本实施例取0.03，扰动半径为$ρ_{rel}‖h_{ij}‖_2$；$∇_{h_{ij}}J_{err}$为监督损失对条件联合表示的梯度，$‖·‖_2$为向量的欧氏范数，$ε$为防止分母为零的正数，本实施例取$10^{-8}$；扰动后表示$h̃_{ij}$由原表示与$δ_{ij}$相加得到。关系判断模块和证据贡献核验子模块的参数在生成扰动时固定，同时保留对条件表示的梯度。扰动后重新执行错误检测，保留实际产生可检测错误且必要信息完整的样本用于局部恢复训练。局部校正子模块读取错误位置及现有材料，以恢复$F^*$的关系、引用和状态为目标；自然错误及正确样本同时用于训练和验证纠错与误改情况。金额边界数据$B$用于复核金额结果，审计路径$T$记录实际处理引用及修改范围。', 29)
